  @protected
  void sse_encode_qr_state(QrState self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case QrState_Expired():
        sse_encode_i_32(0, serializer);
      case QrState_Waiting():
        sse_encode_i_32(1, serializer);
      case QrState_Scanned(
        nickname: final nickname,
        avatarUrl: final avatarUrl,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_String(nickname, serializer);
        sse_encode_opt_String(avatarUrl, serializer);
      case QrState_Authorized():
        sse_encode_i_32(3, serializer);
      case QrState_Failed(message: final message):
        sse_encode_i_32(4, serializer);
        sse_encode_String(message, serializer);
    }
  }

