  @protected
  void sse_encode_ui_event(UiEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case UiEvent_State(field0: final field0):
        sse_encode_i_32(0, serializer);
        sse_encode_player_state(field0, serializer);
      case UiEvent_Position(
        positionMs: final positionMs,
        durationMs: final durationMs,
        buffered: final buffered,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_i_64(positionMs, serializer);
        sse_encode_i_64(durationMs, serializer);
        sse_encode_f_32(buffered, serializer);
      case UiEvent_TrackChanged(field0: final field0):
        sse_encode_i_32(2, serializer);
        sse_encode_opt_box_autoadd_song_item(field0, serializer);
      case UiEvent_QueueChanged():
        sse_encode_i_32(3, serializer);
      case UiEvent_SettingsChanged():
        sse_encode_i_32(4, serializer);
      case UiEvent_DownloadsChanged():
        sse_encode_i_32(5, serializer);
      case UiEvent_Notice(field0: final field0):
        sse_encode_i_32(6, serializer);
        sse_encode_String(field0, serializer);
      case UiEvent_Error(field0: final field0):
        sse_encode_i_32(7, serializer);
        sse_encode_String(field0, serializer);
    }
  }

